examples.template:
MonarchRunningTimer(
    startedAt: startedAt,
    label: note.isEmpty ? nil : note,
    labels: MonarchRunningTimerLabels(start: {{startLabel}}),
    onStart: { startedAt = .now },
    onStop: { startedAt = nil },
    onStopAt: { _ in startedAt = nil },
    onDiscard: { startedAt = nil }
) {
    MonarchTextField({{fieldLabel}}, text: $note)
}

examples.code:
MonarchRunningTimer(
    startedAt: startedAt,
    label: note.isEmpty ? nil : note,
    labels: MonarchRunningTimerLabels(start: "Start timer"),
    onStart: { startedAt = .now },
    onStop: { startedAt = nil },
    onStopAt: { _ in startedAt = nil },
    onDiscard: { startedAt = nil }
) {
    MonarchTextField("What are you working on?", text: $note)
}

MonarchRunningTimer(
    startedAt: startedAt,
    isStartDisabled: project.isEmpty,
    onStart: { startedAt = .now },
    onStop: { startedAt = nil },
    fields: {
        Picker("Project", selection: $project) {
            Text("Atlas").tag("Atlas")
            Text("Pulse").tag("Pulse")
        }
    }
)
